package cz.mh.rallye.rallye_backend.participation;
import java.time.*;import java.util.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;import org.springframework.context.annotation.Import;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;import jakarta.servlet.http.Cookie;
import cz.mh.rallye.rallye_backend.participation.api.*;import cz.mh.rallye.rallye_backend.participation.application.*;import cz.mh.rallye.rallye_backend.races.application.EventService.Content;import cz.mh.rallye.rallye_backend.identity.api.*;import cz.mh.rallye.rallye_backend.identity.application.*;
import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(ParticipantController.class) @Import({AuthConfiguration.class,AuthCookies.class,ApiErrors.class,StartCodePrivacyFilter.class})
class ParticipantHttpTest {
 @Autowired MockMvc mvc;@MockitoBean AuthService auth;@MockitoBean ParticipantReadService service;
 final UUID reg=UUID.randomUUID(),run=UUID.randomUUID();final String token=new SecretTokens().create(),base="/api/v1/race-participations/"+reg;
 ParticipantReadService.View view(){return new ParticipantReadService.View(reg,run,1,2,3,"RUNNING",Instant.EPOCH,"ENDED",Instant.EPOCH,null,"-9223372036854775808");}
 @Test void deviceHeaderWithoutAccountOrCsrfReturnsExactContractAndPrivacy()throws Exception{when(service.current(token,reg)).thenReturn(view());var result=mvc.perform(get(base+"/current-run").header("Authorization","Race "+token)).andExpect(status().isOk()).andExpect(jsonPath("$.runId").value(run.toString())).andExpect(jsonPath("$.status").value("RUNNING")).andExpect(jsonPath("$.eventStatus").value("ENDED")).andExpect(jsonPath("$.totalPenaltyPoints").value("-9223372036854775808")).andExpect(header().string("Cache-Control","no-store")).andExpect(header().string("Referrer-Policy","no-referrer")).andExpect(header().doesNotExist("Set-Cookie")).andReturn();assertFalse(result.getResponse().getContentAsString().contains(token));verifyNoInteractions(auth);}
 @Test void accountCookieAndBearerNeverReplaceRaceToken()throws Exception{for(String header:List.of("Bearer "+token,"Race bad")){mvc.perform(get(base+"/current-run").header("Authorization",header)).andExpect(status().isUnauthorized()).andExpect(jsonPath("$.code").value("RACE_DEVICE_INVALID")).andExpect(header().string("Referrer-Policy","no-referrer"));}mvc.perform(get(base+"/current-run").cookie(new Cookie(AuthCookies.NAME,token))).andExpect(status().isUnauthorized()).andExpect(jsonPath("$.code").value("RACE_DEVICE_INVALID"));verifyNoInteractions(service,auth);}
 @Test void expiredAccountCookieDoesNotInterfereWithIndependentDevice()throws Exception{when(service.current(token,reg)).thenReturn(view());mvc.perform(get(base+"/current-run").header("Authorization","Race "+token).cookie(new Cookie(AuthCookies.NAME,"expired"))).andExpect(status().isOk()).andExpect(header().doesNotExist("Set-Cookie"));verifyNoInteractions(auth);}
 @Test void revokedAndForeignDeviceErrorsDoNotDiscloseRegistration()throws Exception{when(service.current(eq(token),any())).thenThrow(new AuthFailure(401,"RACE_DEVICE_INVALID"));for(UUID id:List.of(reg,UUID.randomUUID()))mvc.perform(get("/api/v1/race-participations/"+id+"/current-run").header("Authorization","Race "+token)).andExpect(status().isUnauthorized()).andExpect(jsonPath("$.code").value("RACE_DEVICE_INVALID")).andExpect(header().string("Cache-Control","no-store"));}
 @Test void duplicateAuthorizationIsRejectedBeforeApplication()throws Exception{mvc.perform(get(base+"/current-run").header("Authorization","Race "+token,"Race "+token)).andExpect(status().isUnauthorized());verifyNoInteractions(service);}
 @Test void pdfIsAttachmentAndMarkdownUsesRestrictiveCsp()throws Exception{when(service.file(token,reg,"map.pdf")).thenReturn(new Content("map.pdf","application/pdf",new byte[]{1,2},false,true));mvc.perform(get(base+"/files/map.pdf").header("Authorization","Race "+token)).andExpect(status().isOk()).andExpect(content().contentType("application/pdf")).andExpect(header().string("Content-Disposition",org.hamcrest.Matchers.startsWith("attachment;"))).andExpect(header().string("Content-Security-Policy","default-src 'none'; sandbox")).andExpect(header().string("X-Content-Type-Options","nosniff")).andExpect(header().string("Cache-Control","no-store"));when(service.file(token,reg,"guide.md")).thenReturn(new Content("guide.md","text/html;charset=UTF-8","safe".getBytes(),true,false));mvc.perform(get(base+"/files/guide.md").header("Authorization","Race "+token)).andExpect(status().isOk()).andExpect(content().contentType("text/html;charset=UTF-8")).andExpect(header().string("Content-Security-Policy",org.hamcrest.Matchers.containsString("script-src 'none'"))).andExpect(header().doesNotExist("Set-Cookie"));}
 @Test void forbiddenMissingFilesHaveIdentical404AndPrivacy()throws Exception{when(service.file(eq(token),eq(reg),any())).thenThrow(new AuthFailure(404,"RACE_FILE_NOT_FOUND"));for(String file:List.of("future.md","missing.pdf",UUID.randomUUID().toString()))mvc.perform(get(base+"/files/"+file).header("Authorization","Race "+token)).andExpect(status().isNotFound()).andExpect(jsonPath("$.code").value("RACE_FILE_NOT_FOUND")).andExpect(header().string("Referrer-Policy","no-referrer"));mvc.perform(get(base+"/files/future.md")).andExpect(status().isUnauthorized()).andExpect(jsonPath("$.code").value("RACE_DEVICE_INVALID"));}
 @Test void deviceCannotAuthenticateAccountAdminOrEventLibrary()throws Exception{for(String path:List.of("/api/v1/auth/me","/api/v1/admin/about","/api/v1/race-events/"+reg+"/files/map.pdf"))mvc.perform(get(path).header("Authorization","Race "+token)).andExpect(status().isUnauthorized());verifyNoInteractions(service);}
}
